INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62785754', 62785754, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Lisensi Monitoring Jaringan Pada Direktorat Teknologi Informasi Direktorat Jenderal Kekayaan Intelektual Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 900000000, 'March 2026', 'APBN - PNBP (D)', 1, 0, '1 Paket', 'Lisensi untuk platform pemantauan jaringan dan pengalaman pengguna yang mampu memberikan visibilitas end-to-end, mencakup seluruh jalur koneksi dari perangkat pengguna hingga aplikasi yang digunakan masyarakat. Platform ini menyediakan kemampuan pemetaan jalur koneksi secara visual (path visualization), pemantauan kualitas jaringan di berbagai lokasi, analisis performa aplikasi yang bergantung pada internet dan cloud, deteksi dini gangguan di luar jaringan DJKI, notifikasi otomatis terhadap degradasi layanan, serta dukungan analitik untuk mempercepat troubleshooting dan pengambilan keputusan.', '- Merupakan platform Digital Experience Monitoring (DEM) yang menyediakan visibilitas end-to-end dari pengguna hingga aplikasi melalui berbagai lingkungan jaringan seperti internet, cloud, dan layanan SaaS. - Platform ini mengumpulkan telemetri dari berbagai titik pemantauan untuk memberikan informasi menyeluruh terkait performa jaringan dan aplikasi. - Mendukung berbagai metode pengujian layanan dan aplikasi, termasuk pengujian konektivitas, server, serta simulasi akses dan transaksi pengguna. - Agen monitoring dapat dijalankan secara fleksibel pada perangkat jaringan maupun server berbasis sistem operasi Linux, serta didukung oleh agen cloud yang tersebar secara global untuk kebutuhan pengujian dari berbagai lokasi. - Menyediakan pemantauan performa jaringan dan aplikasi secara real-time dengan metrik utama seperti latency, packet loss, bandwidth, dan jitter, lengkap dengan sistem notifikasi yang dapat dikonfigurasi. - Dapat terintegrasi dengan sistem manajemen jaringan yang sudah ada untuk memudahkan deployment dan pengelolaan agen monitoring. - Dilengkapi dengan dashboard terpusat untuk visualisasi data, notifikasi, dan pelaporan guna mendukung analisis performa secara menyeluruh. - Menggunakan skema lisensi berbasis token dengan periode penggunaan bulanan dalam kontrak jangka waktu tertentu.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 54412);
