INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62785714', 62785714, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Perpanjangan Lisensi Security Operation Center (SOC) Pada Direktorat Teknologi Informasi Direktorat Jenderal Kekayaan Intelektual Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 6090000000, 'March 2026', 'APBN - PNBP (D)', 1, 0, '1 Paket', 'Perpanjangan lisensi selama 1 tahun untuk dukungan layanan Security Operation Center (SOC) yang andal dan berkelanjutan untuk melakukan pemantauan, deteksi, analisis, dan respons terhadap insiden keamanan siber secara terpusat dan terintegrasi. Layanan SOC tersebut mencakup kemampuan Threat Intelligence, Network Detection and Response (NDR), Security Information and Event Management (SIEM), User and Entity Behavior Analytics (UEBA), serta Security Orchestration, Automation, and Response (SOAR) guna meningkatkan efektivitas pengelolaan keamanan informasi.', '- Pekerjaan ini merupakan perpanjangan lisensi dan dukungan solusi Open-XDR berbasis AI untuk deteksi dan respons ancaman keamanan siber secara terintegrasi. - Perpanjangan mencakup lisensi perangkat lunak berbasis tahunan dengan model lisensi tunggal yang meliputi seluruh fitur dan kapabilitas keamanan, termasuk analisis dan pengolahan log, data lake, integrasi threat intelligence, fungsi SIEM, sandbox, IDS, network traffic analysis (NTA), manajemen aset, user behavior analytics (UBA), threat hunting, serta otomatisasi respons. - Termasuk perpanjangan kapasitas pemrosesan dan ingest data, lisensi data processor, serta langganan dan operasional security sensor yang dapat diimplementasikan dalam berbagai bentuk (virtual, agent, maupun container) sesuai kebutuhan. - Perpanjangan juga mencakup dukungan teknis serta garansi perangkat keras selama masa kontrak.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 54467);
