INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62785711', 62785711, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL KEKAYAAN INTELEKTUAL', 'Pengadaan Langganan Google Cloud Pada Direktorat Teknologi Informasi Direktorat Jenderal Kekayaan Intelektual Tahun Anggaran 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 360000000, 'March 2026', 'APBN - PNBP (D)', 1, 0, '1 Paket', 'Lisensi Google Cloud merupakan layanan komputasi awan yang ditawarkan oleh Google yang menyediakan berbagai layanan, seperti komputasi, penyimpanan data, analisis data, dan pembelajaran mesin.', 'Lisensi Google Cloud diperlukan untuk pemanfaatan layanan AI dan keamanan digital melalui Google Cloud Platform (GCP), meliputi: 1) Google Translate API untuk translasi permohonan internasional seperti Madrid Protocol ke Bahasa Indonesia, 2) Natural Language AI untuk normalisasi data pemohon dan alamat yang selama ini berbentuk freetext, dan 3) reCAPTCHA Enterprise untuk perlindungan aplikasi web dari serangan brute force dan aktivitas bot. Estimasi volume mencakup 6 juta karakter translasi/tahun, 600.000 permintaan NLP/tahun, dan 1,2 juta validasi captcha/tahun. Layanan berbasis cloud ini mendukung otomatisasi, akurasi data, serta peningkatan keamanan dan efisiensi sistem layanan publik DJKI lintas rezim Kekayaan Intelektual', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 55861);
