INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61936301', 61936301, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Penyusunan Dokumen Teknis Gedung Pemda - (Arsitektur 5) - SAPS 5 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Senior Assistant Professional Staff penunjang Seksi Pembangunan dan Perawatan Gedung Pemerintah Daerah sesuai dengan bidang keahlian Arsitektur wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut: a. Membantu pemeriksaan kelengkapan standar teknis bangunan gedung bidang arsitektur dan penerbitan surat pernyataan pemenuhan standar teknis dalam rangka Persetujuan Bangunan Gedung dan Sertifikat Laik Fungsi (SLF) bangunan Gedung; b. Membantu penyusunan perencanaan teknis pembangunan, perawatan dan pemeliharaan bangunan gedung pemerintah daerah; c. Membantu memeriksa dan mengkaji kembali (review) dokumen perencanaan yang dibuat oleh jasa konsultan perencana maupun yang dibuat oleh Seksi Pembinaan Gedung Pemda (in house) terutama di awal pelaksanaan pembangunan pekerjaan fisik dan menyampaikan usulan penyempurnaan bila didapati kekurangan/ketidaksesuaian dalam perencanaan konsultan, sehingga pekerjaan dapat dilaksanakan secara efektif, efisien dan bangunan nantinya dapat berfungsi secara optimal ; Catatan : *Beberapa tugas tambahan lain baik teknis maupun non teknis, akan disesuaikan dengan permintaan Suku Dinas Cipta Karya, Tata Ruang dan Pertanahan Kota Adm. Jakarta Pusat. "', '"Senior Assistant Profesional Staff bidang Arsitektur dengan ketentuan sebagai berikut : - S0/S1 Teknik Arsitektur/ Interior - Pengalaman kerja minimal 1 tahun di bidangnya - Mampu menyusun dan menganalisa Gambar Kerja, RAB, RKS, BoQ dan Kurva S - Memiliki pengetahuan dan/atau pengalaman di bidang perencanaan, pembangunan, dan pengawasan pelaksanaan konstruksi Gedung"', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 55874);
