INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61941634', 61941634, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Penyusunan Dokumen Teknis Gedung Pemda - (Sipil 1) - SAPS 6 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 82582500, 'December 2025', 'APBD', 1, 1, '1 Paket', '"Senior Assistant Professional Staff penunjang Seksi Pembangunan dan Perawatan Gedung Pemerintah Daerah sesuai dengan bidang keahlian Struktur wajib melaksanakan dan menyelesaikan pekerjaan sebagai berikut: a. Membantu memeriksa dan mengkaji kembali (review) dokumen struktur perencanaan yang dibuat oleh jasa konsultan perencana maupun yang dibuat oleh Seksi Pembinaan Gedung Pemda (in house) terutama di awal pelaksanaan pembangunan pekerjaan fisik dan menyampaikan usulan penyempurnaan bila didapati kekurangan/ketidaksesuaian dalam perencanaan konsultan, sehingga pekerjaan dapat dilaksanakan secara efektif, efisien dan bangunan nantinya dapat berfungsi secara optimal ; b. Membantu memeriksa dan mengkaji kembali (review) kesesuaian volume pekerjaan struktur antara gambar kerja dengan Rencana Anggaran Biaya (RAB) terutama di awal pelaksanaan pekerjaan fisik dan menyampaikan usulan penyempurnaan bila didapati ketidaksesuaian; c. Membantu mengawasi pelaksanaan pekerjaan struktur yang dilaksanakan oleh Kontraktor dari segi kualitas, kuantitas dan laju pencapaian prestasi pekerjaan; d. Melaporkan dan memberikan saran atas hasil pekerjaan struktur yang tidak memenuhi persyaratan; e. Membantu membuat kelengkapan administrasi sebagai bagian dari penertiban pelaksanaan pembangunan fisik sesuai dengan ketentuan yang berlaku; Catatan : *Beberapa tugas tambahan lain baik teknis maupun non teknis, akan disesuaikan dengan permintaan Suku Dinas Cipta Karya, Tata Ruang dan Pertanahan Kota Adm. Jakarta Pusat. "', '"Senior Assistant Profesional Staff bidang Strtuktur dengan ketentuan sebagai berikut : - S0/S1 Teknik Sipil - Pengalaman kerja minimal 1 tahun di bidangnya - Mampu menyusun dan menganalisa Gambar Kerja, RAB, RKS, BoQ dan Kurva S - Memiliki pengetahuan dan/atau pengalaman di bidang perencanaan, pembangunan, dan pengawasan pelaksanaan konstruksi Gedung"', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 57080);
