INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62807949', 62807949, 'analyze_legacy', 'Kab. Balangan', 'kabkota', 'DINAS PEKERJAAN UMUM, PENATAAN RUANG, PERUMAHAN RAKYAT DAN KAWASAN PEMUKIMAN', 'Perencanaan Pembangunan Restorative Justice (RJ) Desa Mamigang Kec. Halong', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Kalimantan Selatan, Balangan (Kab.)', 15000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Perencanaan Pembangunan Restorative Justice (RJ) Desa Mamigang Kec. Halong', 'Spesifikasi di KAK', 15000000, 'high', 'Objek pengadaan berupa perencanaan pembangunan fasilitas/program Restorative Justice tampak kurang selaras dengan fungsi utama unit pekerjaan umum/perumahan. Dari judul item, indikasinya adalah penggunaan anggaran pada kegiatan yang lebih dekat dengan urusan hukum/sosial daripada mandat teknis infrastruktur satker, sehingga patut dinilai berisiko tidak tepat guna.', NULL, NULL, 3, 1, 1, 1, 1, 59997);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62785949', 62785949, 'analyze_legacy', 'Kab. Probolinggo', 'kabkota', 'Sekretariat DPRD', 'Belanja Sewa Tanaman untuk Kegiatan Penyediaan Jasa Penunjang Urusan Pemerintahan Daerah Sub Kegiatan Penyediaan Jasa Peralatan dan Perlengkapan Kantor (PAD)', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Probolinggo (Kab.)', 96000000, 'January 2026', 'APBD', 1, 1, '24 Paket', 'Sewa Tanaman Hias', 'Spesifikasi: 20 Jenis Tanaman : 2 Paket x 12 Bulan', 96000000, 'high', 'Pengadaan sewa tanaman hias untuk lingkungan Sekretariat DPRD berindikasi belanja penunjang estetika yang tidak esensial terhadap fungsi utama layanan publik. Dengan nilai anggaran penuh untuk sewa selama 12 bulan, item ini layak dinilai sebagai potensi pemborosan karena manfaat langsung terhadap kinerja pemerintahan tidak jelas dari data yang tersedia.', NULL, NULL, 3, 1, 1, 1, 1, 59998);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62808077', 62808077, 'analyze_legacy', 'Kab. Balangan', 'kabkota', 'DINAS PEKERJAAN UMUM, PENATAAN RUANG, PERUMAHAN RAKYAT DAN KAWASAN PEMUKIMAN', 'Pengawasan Pembangunan Restorative Justice (RJ) Desa Tanah Habang Kanan Kec. Lampihong', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Kalimantan Selatan, Balangan (Kab.)', 15000000, 'January 2026', 'APBD', 1, 1, '1 Paket', 'Pengawasan Pembangunan Restorative Justice (RJ) Desa Tanah Habang Kanan Kec. Lampihong', 'Spesifikasi di KAK', 15000000, 'high', 'Item pengawasan pembangunan fasilitas restorative justice oleh dinas pekerjaan umum berpotensi tidak selaras dengan fungsi utama belanja infrastruktur daerah. Dari judul, objek pengadaan lebih dekat dengan program penegakan hukum/kelembagaan sehingga relevansi penggunaan anggaran melalui satker ini patut dipertanyakan. Seluruh nilai paket layak dicermati sebagai potensi pemborosan bila kegiatan tersebut bukan kebutuhan yang tepat bagi urusan satker.', NULL, NULL, 3, 1, 1, 1, 1, 59999);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61942120', 61942120, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU BADAN PENGELOLAAN ASET DAERAH KABUPATEN - KEP. SERIBU', 'Penyediaan Jasa Petugas Penunjang Kegiatan Kantor / Lapangan', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Adm. Kepulauan Seribu (Kab.)', 91145925, 'December 2025', 'APBD', 1, 1, '1 Tahun', '- Membantu bendahara dalam melakukan pencarian SPM/SPP kegiatan - Membantu bendahara dalam melakukan tutup buku bulanan dan tahunan - Melakukan kegiatan surat menyurat - Mendampingi kegiatan rekonsiliasi dan inventarisasi BMD pada Suku Badan Pengelolaan Aset Daerah Kabupaten Administrasi Kepulauan Seribu', '- Pendidikan minimal S1 umum - Mampu mengoperasikan komputer dan familiar dengan internet', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 60000);
